.row{display:grid;gap:12px}
.grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}
.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}
.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:12px;box-shadow:var(--shadow)}
.card h3{margin:0 0 8px;font-size:14px;color:#c9d1eb}
.metric{font-size:24px;font-weight:700}
.badge{display:inline-block;padding:3px 8px;border-radius:999px;font-size:12px;font-weight:600}
.pos{color:var(--green)}
.neg{color:var(--red)}
.badge.pos{background:rgba(46,212,122,.16)}
.badge.neg{background:rgba(255,92,108,.16)}
.table{width:100%;border-collapse:collapse;font-size:13px}
.table th,.table td{padding:8px 6px;border-bottom:1px solid #2a2f4a;text-align:left}
.table th{color:var(--muted);font-weight:600}
.spark{height:28px;width:90px}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}
.tab{padding:7px 10px;border:1px solid var(--border);border-radius:8px;background:var(--panel-2);color:var(--muted);cursor:pointer;font-size:12px}
.tab.active{color:var(--text);border-color:var(--blue);box-shadow:inset 0 0 0 1px rgba(46,168,255,.35)}
.panel{display:none}
.panel.active{display:block}
.terminal-layout{display:grid;grid-template-columns:280px 1fr 310px;gap:12px;min-height:74vh}
.watch-group{margin-bottom:8px}
.watch-head{display:flex;justify-content:space-between;align-items:center;padding:8px 10px;background:var(--panel-2);border-radius:8px;cursor:pointer;font-size:12px;color:#c9d1eb}
.watch-body{margin-top:6px}
.watch-row{display:grid;grid-template-columns:1fr auto auto;gap:8px;padding:7px 8px;border-radius:8px;font-size:12px}
.watch-row:hover{background:#202542}
.chart-toolbar{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:8px}
.tf button{background:var(--panel-2);border:1px solid var(--border);color:#c9d1eb;padding:6px 8px;border-radius:6px;font-size:12px;cursor:pointer}
.tf button.active{border-color:var(--blue);color:#fff}
.chart-wrap{height:420px;background:linear-gradient(180deg,#171a30,#14172a);border:1px solid var(--border);border-radius:10px;padding:10px}
.candle-svg{width:100%;height:100%}
.kv{display:grid;grid-template-columns:1fr auto;gap:8px;font-size:13px;padding:6px 0;border-bottom:1px solid #2a2f4a}
.hero{display:grid;grid-template-columns:2fr 1fr;gap:12px}
.cta{background:linear-gradient(145deg,#1f2443,#1a3550);border:1px solid #37507d;padding:16px;border-radius:12px}
.btn{background:var(--blue);border:none;color:#fff;padding:9px 12px;border-radius:8px;font-weight:600;cursor:pointer}
.small{font-size:12px;color:var(--muted)}
@media (max-width:1200px){.terminal-layout{grid-template-columns:1fr}.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto}}
@media (max-width:900px){.grid-4,.grid-3,.grid-2,.hero{grid-template-columns:1fr}}
EOF

cat > /app/output/app.js << 'EOF'
document.querySelectorAll('[data-tabs]').forEach((group) => {
  const tabs = group.querySelectorAll('[data-tab]');
  const panels = group.querySelectorAll('[data-panel]');
  tabs.forEach((tab) => tab.addEventListener('click', () => {
    const target = tab.getAttribute('data-tab');
    tabs.forEach(t => t.classList.remove('active'));
    panels.forEach(p => p.classList.remove('active'));
    tab.classList.add('active');
    const panel = group.querySelector(`[data-panel="${target}"]`);
    if(panel) panel.classList.add('active');
  }));
});

document.querySelectorAll('[data-accordion]').forEach((head)=>{
  head.addEventListener('click',()=>{
    const body = head.nextElementSibling;
    const open = body.style.display !== 'none';
    body.style.display = open ? 'none':'block';
  })
});

document.querySelectorAll('.tf button').forEach((b)=>b.addEventListener('click',()=>{
  b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');
}));
EOF

