.kv{display:grid;grid-template-columns:1fr auto;gap:8px;font-size:13px;padding:6px 0;border-bottom:1px solid #2a2f4a}
.hero{display:grid;grid-template-columns:2fr 1fr;gap:12px}
.cta{background:linear-gradient(145deg,#1f2443,#1a3550);border:1px solid #37507d;padding:16px;border-radius:12px}
.btn{background:var(--blue);border:none;color:#fff;padding:9px 12px;border-radius:8px;font-weight:600;cursor:pointer}
.small{font-size:12px;color:var(--muted)}
@media (max-width:1200px){.terminal-layout{grid-template-columns:1fr}.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto}}
@media (max-width:900px){.grid-4,.grid-3,.grid-2,.hero{grid-template-columns:1fr}}
EOF

cat > /app/output/app.js << 'EOF'
document.querySelectorAll('[data-tabs]').forEach((group) => {
  const tabs = group.querySelectorAll('[data-tab]');
  const panels = group.querySelectorAll('[data-panel]');
  tabs.forEach((tab) => tab.addEventListener('click', () => {
    const target = tab.getAttribute('data-tab');
    tabs.forEach(t => t.classList.remove('active'));
    panels.forEach(p => p.classList.remove('active'));
    tab.classList.add('active');
    const panel = group.querySelector(`[data-panel="${target}"]`);
    if(panel) panel.classList.add('active');
  }));
});

document.querySelectorAll('[data-accordion]').forEach((head)=>{
  head.addEventListener('click',()=>{
    const body = head.nextElementSibling;
    const open = body.style.display !== 'none';
    body.style.display = open ? 'none':'block';
  })
});

document.querySelectorAll('.tf button').forEach((b)=>b.addEventListener('click',()=>{
  b.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));
  b.classList.add('active');
}));
EOF

